class Solution {
public:
    vector<int> maxSumOfThreeSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int m = n - k + 1;
        vector<long long> w(m);
        long long s = 0;
        for (int i = 0; i < k; i++) s += nums[i];
        w[0] = s;
        for (int i = 1; i < m; i++) {
            s += nums[i + k - 1] - nums[i - 1];
            w[i] = s;
        }
        vector<int> leftMax(m);
        leftMax[0] = 0;
        for (int i = 1; i < m; i++) {
            leftMax[i] = (w[i] > w[leftMax[i - 1]]) ? i : leftMax[i - 1];
        }
        vector<int> rightMax(m);
        rightMax[m - 1] = m - 1;
        for (int i = m - 2; i >= 0; i--) {
            rightMax[i] = (w[i] >= w[rightMax[i + 1]]) ? i : rightMax[i + 1];
        }
        long long best = -1;
        vector<int> ans(3);
        for (int j = k; j + k <= m - 1; j++) {
            int l = leftMax[j - k];
            int r = rightMax[j + k];
            long long total = w[l] + w[j] + w[r];
            if (total > best) {
                best = total;
                ans[0] = l;
                ans[1] = j;
                ans[2] = r;
            }
        }
        return ans;
    }
};
